using System.Security.Cryptography.X509Certificates;

namespace DK.Gov.Oio.Saml.Tests.Builders;

// Issued by the NemLog-in test CA ("Den Danske Stat OCES udstedende-CA 1", Test - cti), whose OCSP responder and CRL
// at ca1.cti-gov.dk know one as good and the other as revoked. Tests using them need network access.
public static class NemLogInTestCertificates
{
    public static X509Certificate2 DevTest4IdpSigning => Load("");

    public static X509Certificate2 Revoked => Load("");

    private static X509Certificate2 Load(string base64) => X509CertificateLoader.LoadCertificate(Convert.FromBase64String(base64));
}
